export type Mode = "normal" | "pro";

export const MODES: { id: Mode; label: string; hint: string }[] = [
  { id: "normal", label: "标准", hint: "最强模型 · 不开深度思考,出稿快" },
  { id: "pro", label: "专家", hint: "最强模型 · 开启深度思考,更慢但质量更高" },
];

// 两档共用同一个「最强模型」,差别只在是否开 reasoning(见 reasoningForMode)。
// 优先读 OPENAI_MODEL;兼容旧的 OPENAI_MODEL_PRO/NORMAL;都没有则用默认值。
export function modelForMode(_mode?: string): string {
  return (
    process.env.OPENAI_MODEL ||
    process.env.OPENAI_MODEL_PRO ||
    process.env.OPENAI_MODEL_NORMAL ||
    "kimi-k2.6"
  );
}

// 标准档关思考(快),专家档开思考(慢、质量高)。
export function reasoningForMode(mode?: string): boolean {
  return mode === "pro";
}

