// ---- few-shot 范例(只读)----

export async function getFewshot(): Promise<FewshotExample[]> {
  try {
    const raw = await readJson<unknown>(FEWSHOT_PATH);
    if (!Array.isArray(raw)) return [];
    return raw.filter((e): e is FewshotExample => {
      const o = e as Record<string, unknown> | null;
      const out = o?.output as Record<string, unknown> | undefined;
      return (
        !!o &&
        typeof o.input === "string" &&
        !!out &&
        typeof out.text === "string"
      );
    });
  } catch {
    return [];
  }
}

