import {
  getBrandFacts,
  getFewshot,
  getStylePalette,
  getTerminology,
} from "@/lib/store";
import type {
  BrandFacts,
  FewshotExample,
  PolishRequest,
  RefineRequest,
  StyleEntry,
  UnifiedTerm,
} from "@/lib/types";

const LANG_LABELS: Record<string, string> = {
  auto: "自动识别原文语言",
  same: "与原文保持同一种语言(原文英文就输出英文,中文就输出中文)",
  zh: "简体中文",
  en: "English",
  fr: "Français",
};

function langLabel(code: string): string {
  return LANG_LABELS[code] ?? code;
}

function brandFactsBlock(brandFacts: BrandFacts): string {
  const tone = brandFacts.toneCard;
  const terms = brandFacts.terminology.map((t) => t.preferred).join(";");
  const banned = brandFacts.compliance.bannedPhrases.join("、");
  return [
    `品牌:${brandFacts.brand};声音:${tone.voice}`,
    `宜:${tone.do.join("/")};忌:${tone.dont.join("/")}`,
    `术语统一:${terms}`,
    `合规:含绝对化用语(${banned})只在 risks 标记、不删改;${brandFacts.compliance.healthClaimNote ?? ""}`,
  ].join("\n");
}

// 兜底的通用方向:当用户没勾风格、风格库也不够分时,用这些保证各版本有区分度。
const GENERIC_DIRECTIONS = [
  "简洁有力:一句话抓住核心,去掉所有可省的字",
  "情感共鸣:带出使用场景与真实感受,让人有画面",
  "专业可信:突出品质与匠心,语气稳重克制",
  "活泼新鲜:语气年轻、有网感,但不轻佻",
];

// 给 n 个并发槽位各分配一个「明显不同」的写作方向。
// 优先用用户勾选的风格,其次用风格库默认灵感,最后用通用方向兜底。
export function pickDirections(
  palette: StyleEntry[],
  selectedIds: string[] | undefined,
  n: number
): string[] {
  const fromStyles: string[] = [];
  if (selectedIds && selectedIds.length > 0) {
    const chosen = palette.filter((s) => selectedIds.includes(s.id));
    for (const s of chosen) fromStyles.push(`「${s.name}」方向:${s.essence}`);
  } else {
    const defaults = palette.filter((s) => s.isDefault);
    const reps = (defaults.length > 0 ? defaults : palette).slice(0, n);
    for (const s of reps) fromStyles.push(`「${s.name}」方向:${s.essence}`);
  }

  const out: string[] = [];
  for (let i = 0; i < n; i++) {
    out.push(fromStyles[i] ?? GENERIC_DIRECTIONS[i % GENERIC_DIRECTIONS.length]);
  }
  return out;
}

// 软参考:扫原文命中的统一表述术语,把它们的各语言标准写法作为「术语对照」给模型。
const MAX_TERM_REFS = 40;

function termReferenceBlock(input: string, unified: UnifiedTerm[]): string {
  if (unified.length === 0) return "";
  const hay = input.toLowerCase();
  const matched: UnifiedTerm[] = [];
  for (const t of unified) {
    const forms = [t.zh, t.en, t.fr].filter((s) => s && s.trim());
    const hit = forms.some((f) => f && hay.includes(f.toLowerCase()));
    if (hit) {
      matched.push(t);
      if (matched.length >= MAX_TERM_REFS) break;
    }
  }
  if (matched.length === 0) return "";
  const lines = matched.map((t) => {
    const cols = [t.zh && `中:${t.zh}`, t.en && `EN:${t.en}`, t.fr && `FR:${t.fr}`]
      .filter(Boolean)
      .join("  |  ");
    return `- ${cols}`;
  });
  return [
    "【术语对照(软参考)】下列术语在原文中出现,输出对应语言时请使用这里的标准写法,只统一术语本身的拼写/表达,不要因此改写无关内容,其余文案请自由发挥:",
    ...lines,
  ].join("\n");
}

// few-shot:注入若干「素文 → 美化版」范例,只示范风格手法与输出字段,不是本次内容。
const MAX_FEWSHOT = 2;

function fewshotBlock(examples: FewshotExample[]): string {
  if (examples.length === 0) return "";
  const picked = examples.slice(0, MAX_FEWSHOT);
  const lines = picked.map((e, i) => {
    const o = e.output;
    return [
      `范例${i + 1} 原文:${e.input}`,
      `范例${i + 1} 美化:{"text":${JSON.stringify(o.text)},"focus":${JSON.stringify(o.focus)},"intent":${JSON.stringify(o.intent)},"reason":${JSON.stringify(o.reason)}}`,
    ].join("\n");
  });
  return [
    "【风格范例(只示范手法与字段格式,内容与本次任务无关,严禁照抄其中文字)】",
    ...lines,
  ].join("\n");
}

// 单版本 system prompt:产出 1 个版本(单个 JSON 对象)。
export async function buildSystemPrompt(): Promise<string> {
  const [brandFacts, fewshot] = await Promise.all([
    getBrandFacts(),
    getFewshot(),
  ]);
  const fs = fewshotBlock(fewshot);
  return [
    "你是韶音(Shokz)品牌的资深文案副驾:在忠于原意与事实的前提下,产出可直接使用的品牌化文案(不是逐字翻译)。",
    "",
    "【品牌与规范】",
    brandFactsBlock(brandFacts),
    "",
    "【硬约束(最高优先,凌驾风格)】",
    "1. 事实锚定:产品名/型号/商标不得改写或杜撰;不确定就保留原文。",
    "2. 严禁编造数字与规格:不得新增原文/背景里没有的参数(续航、防水防尘等级、重量、充电时间、价格、销量、排名等);没有就别写,宁可笼统也不编。",
    "3. 不发明卖点,也不写原文未提到的具体产品型号。",
    "4. 术语保持统一。",
    "5. 忠于篇幅:输出长度与原文相称,原文短就给精炼版,不扩写、不加原文没有的场景或属性。",
    "6. 忠于版式:输出结构跟随原文。原文是纯句子/纯段落就只输出句子/段落,不得新增标题、小标题、列表等原文没有的结构;原文自带标题则保留并美化该标题,不删不改其层级。",
    "7. 严禁原样返回:必须是经过改写/美化的文案,不得把原文逐字照搬(仅大小写、空格或标点不同也算照搬)。即使原文已是目标语言、即使原文很短,也必须换一种表达重新写过。此条只针对整句/整段照搬,不影响第1条对产品名/型号/商标的保留。",
    "",
    "【语言规则】",
    "- text 用目标语言;目标为「与原文相同」时先判断原文语言再用该语言写。不要因本提示是中文就把 text 写成中文。",
    "- focus/intent/reason 一律用简体中文,各一句、简短直白。",
    fs ? "" : null,
    fs || null,
    "",
    "【输出】只产出 1 个版本,严格按指定方向写,务必与其它方向有明显区分。只返回一个 JSON 对象(不是数组)。",
  ]
    .filter((x) => x !== null)
    .join("\n");
}

const SINGLE_OUTPUT_SPEC = [
  "只返回一个 JSON 对象,不要任何额外文字或 markdown。字段顺序务必如下(text 在最前):",
  '{"text":"美化/翻译后的文案","focus":"方向名(中文,简短)","intent":"意向(中文,一句)","reason":"理由(中文,一句)","risks":["命中的合规/风险提示,无则空数组"],"detectedSourceLang":"识别到的原文语言"}',
].join("\n");

// 单版本 user prompt:带上本槽位的指定方向。
export async function buildUserPrompt(
  req: PolishRequest,
  direction: string
): Promise<string> {
  const terminology = await getTerminology();
  const parts: string[] = [];
  parts.push(
    `原文语言:${langLabel(req.sourceLang)};目标语言:${langLabel(req.targetLang)}`
  );
  if (req.channel) parts.push(`渠道:${req.channel}`);
  parts.push("");
  parts.push(`【本版指定方向(必须遵循)】${direction}`);

  const termRefs = termReferenceBlock(req.input, terminology);
  if (termRefs) {
    parts.push("");
    parts.push(termRefs);
  }
  if (req.background && req.background.trim()) {
    parts.push("");
    parts.push("【背景参考(仅作上下文,不要翻译这段)】");
    parts.push(req.background.trim().slice(0, 4000));
  }
  parts.push("");
  parts.push("【待润色原文】");
  parts.push(req.input.trim());
  parts.push("");
  parts.push(SINGLE_OUTPUT_SPEC);
  return parts.join("\n");
}

// 精修 system prompt:对已生成的一版做第二轮自检润色,不换方向、不换语言。
export async function buildRefineSystemPrompt(): Promise<string> {
  const brandFacts = await getBrandFacts();
  return [
    "你是韶音(Shokz)品牌的资深文案审校:对「已生成的一版文案」做第二轮精修,使其更顺、更有品牌腔调、更可直接使用。",
    "",
    "【品牌与规范】",
    brandFactsBlock(brandFacts),
    "",
    "【精修要求】",
    "1. 保持原方向、原语言、原大致篇幅,不另起炉灶。",
    "2. 自检并修正:用词是否符合品牌声音、是否有更自然的表达、节奏是否更好。",
    "3. 严守硬约束:不得新增原文/背景没有的数字、规格、型号、卖点;产品名/商标不得改写。",
    "4. 命中绝对化用语或编造风险时写进 risks,不要为了好听去编。",
    "",
    "【输出】只返回一个 JSON 对象(不是数组)。",
  ].join("\n");
}

export async function buildRefineUserPrompt(req: RefineRequest): Promise<string> {
  const terminology = await getTerminology();
  const parts: string[] = [];
  parts.push(
    `原文语言:${langLabel(req.sourceLang)};目标语言:${langLabel(req.targetLang)}`
  );
  if (req.channel) parts.push(`渠道:${req.channel}`);
  if (req.focus) parts.push(`本版方向:${req.focus}`);

  const termRefs = termReferenceBlock(req.original + " " + req.text, terminology);
  if (termRefs) {
    parts.push("");
    parts.push(termRefs);
  }
  if (req.background && req.background.trim()) {
    parts.push("");
    parts.push("【背景参考(仅作上下文)】");
    parts.push(req.background.trim().slice(0, 4000));
  }
  parts.push("");
  parts.push("【原始素文(事实以此为准)】");
  parts.push(req.original.trim());
  parts.push("");
  parts.push("【待精修的当前版本】");
  parts.push(req.text.trim());
  parts.push("");
  parts.push(SINGLE_OUTPUT_SPEC);
  return parts.join("\n");
}

