import OpenAI from "openai";
import type { BrandFacts, PolishRequest, RefineRequest } from "@/lib/types";
import {
  buildRefineSystemPrompt,
  buildRefineUserPrompt,
  buildSystemPrompt,
  buildUserPrompt,
} from "@/lib/prompt";
import { modelForMode, reasoningForMode } from "@/lib/models";

input.old_string:
// 创建流式补全:边生成边吐 token,前端逐张渲染卡片
export async function createPolishStream(
  req: PolishRequest
): Promise<AsyncIterable<PolishStreamChunk>> {
  const client = getClient();
  const model = modelForMode(req.mode);

  // k2.5/k2.6 是思考型模型。由"深度思考"开关控制:
  // 开 → 启用 reasoning(质量高但慢,专家档可达 3 分钟),temperature 必须 1.0;
  // 关 → 关闭 reasoning(≤60s),temperature 必须 0.6。
  // 官方 API 只能开/关思考,不能调强度。非 kimi-k2 模型(如 env 覆盖)用 temperature 1。
  const isKimi = model.startsWith("kimi-k2");
  const deep = req.deepThinking === true;

  const params: Record<string, unknown> = {
    model,
    max_tokens: 8000,
    response_format: { type: "json_object" },
    stream: true,
    messages: [
      { role: "system", content: await buildSystemPrompt() },
      { role: "user", content: await buildUserPrompt(req) },
    ],
  };

  if (isKimi) {
    params.thinking = { type: deep ? "enabled" : "disabled" };
    params.temperature = deep ? 1 : 0.6;
  } else {
    params.temperature = 1;
  }

  return client.chat.completions.create(
    params as unknown as Parameters<typeof client.chat.completions.create>[0]
  ) as unknown as AsyncIterable<PolishStreamChunk>;
}

input.new_string:
// 按档位决定思考开关与温度。标准档关思考(快,temp 0.6),专家档开思考(慢但好,temp 1.0)。
// kimi-k2 用官方 thinking 开关;其它模型(env 覆盖)只设温度。
function applyModeParams(
  params: Record<string, unknown>,
  model: string,
  mode?: string
): void {
  const isKimi = model.startsWith("kimi-k2");
  const deep = reasoningForMode(mode);
  if (isKimi) {
    params.thinking = { type: deep ? "enabled" : "disabled" };
    params.temperature = deep ? 1 : 0.6;
  } else {
    params.temperature = deep ? 1 : 0.6;
  }
}

// 创建「单个版本」的流式补全:一个槽位一条请求,按指定方向只写 1 个版本。
// 路由会并发多条,谁先写完谁先在前端成卡——总耗时 = 最慢那条,而非相加。
export async function createVariantStream(
  req: PolishRequest,
  direction: string
): Promise<AsyncIterable<PolishStreamChunk>> {
  const client = getClient();
  const model = modelForMode(req.mode);

  const params: Record<string, unknown> = {
    model,
    max_tokens: 3000,
    response_format: { type: "json_object" },
    stream: true,
    messages: [
      { role: "system", content: await buildSystemPrompt() },
      { role: "user", content: await buildUserPrompt(req, direction) },
    ],
  };
  applyModeParams(params, model, req.mode);

  return client.chat.completions.create(
    params as unknown as Parameters<typeof client.chat.completions.create>[0]
  ) as unknown as AsyncIterable<PolishStreamChunk>;
}

// 精修:对已生成的某一版做第二轮自检润色(按需触发,默认走专家档开思考求质量)。
export async function createRefineStream(
  req: RefineRequest
): Promise<AsyncIterable<PolishStreamChunk>> {
  const client = getClient();
  const model = modelForMode(req.mode);

  const params: Record<string, unknown> = {
    model,
    max_tokens: 3000,
    response_format: { type: "json_object" },
    stream: true,
    messages: [
      { role: "system", content: await buildRefineSystemPrompt() },
      { role: "user", content: await buildRefineUserPrompt(req) },
    ],
  };
  applyModeParams(params, model, req.mode ?? "pro");

  return client.chat.completions.create(
    params as unknown as Parameters<typeof client.chat.completions.create>[0]
  ) as unknown as AsyncIterable<PolishStreamChunk>;
}

