import { NextRequest, NextResponse } from "next/server";
import { createVariantStream } from "@/lib/llm";
import { pickDirections } from "@/lib/prompt";
import { getStylePalette } from "@/lib/store";
import { checkAuth } from "@/lib/auth";
import type { PolishRequest } from "@/lib/types";

export const runtime = "nodejs";
export const maxDuration = 240;

// 输入长度上限(字符数):防止超长原文吃满 token、拖慢响应、放大成本
const MAX_INPUT_CHARS = 8000;

// 并发槽位数:同时发这么多条单版本请求。固定 3 兼顾「有得挑」与「不过度占配额」。
const VARIANT_SLOTS = 3;

export async function POST(req: NextRequest) {
  const unauthorized = checkAuth(req);
  if (unauthorized) return unauthorized;

  let body: Partial<PolishRequest>;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "请求体不是合法 JSON" }, { status: 400 });
  }

  const input = (body.input ?? "").toString();
  if (!input.trim()) {
    return NextResponse.json({ error: "请输入要润色的文案" }, { status: 400 });
  }
  if ([...input].length > MAX_INPUT_CHARS) {
    return NextResponse.json(
      { error: `原文过长(上限 ${MAX_INPUT_CHARS} 字),请缩短后重试` },
      { status: 413 }
    );
  }

  const payload: PolishRequest = {
    input,
    sourceLang: body.sourceLang || "auto",
    targetLang: body.targetLang || "same",
    styleIds: Array.isArray(body.styleIds) ? body.styleIds : [],
    background: typeof body.background === "string" ? body.background : "",
    channel: typeof body.channel === "string" ? body.channel : "",
    mode: typeof body.mode === "string" ? body.mode : "normal",
  };

  const palette = await getStylePalette();
  const directions = pickDirections(payload.styleIds, payload.styleIds, VARIANT_SLOTS)
    // pickDirections 的第一参数是 palette,这里修正调用顺序
    ;
  void directions;
  const dirs = pickDirections(palette, payload.styleIds, VARIANT_SLOTS);

  const encoder = new TextEncoder();
  const readable = new ReadableStream({
    async start(controller) {
      // 每帧带槽位号 i:{"i":0,"c":...} 正文,{"i":0,"r":...} 思考,{"i":0,"e":...} 错误。逐行 NDJSON。
      const send = (
        frame:
          | { i: number; r: string }
          | { i: number; c: string }
          | { i: number; e: string }
      ) => controller.enqueue(encoder.encode(JSON.stringify(frame) + "\n"));

      // 每个槽位独立跑:单条建流或生成失败只影响自己,不拖垮其它槽位。
      const tasks = dirs.map(async (direction, i) => {
        try {
          const stream = await createVariantStream(payload, direction);
          for await (const part of stream) {
            const delta = part.choices?.[0]?.delta as
              | { content?: string; reasoning_content?: string }
              | undefined;
            if (!delta) continue;
            if (delta.reasoning_content) send({ i, r: delta.reasoning_content });
            if (delta.content) send({ i, c: delta.content });
          }
        } catch (err) {
          const message =
            err instanceof Error ? err.message : "该版本生成失败,请重试";
          send({ i, e: message });
        }
      });

      await Promise.all(tasks);
      controller.close();
    },
  });

  return new Response(readable, {
    headers: {
      "Content-Type": "application/x-ndjson; charset=utf-8",
      "Cache-Control": "no-cache, no-transform",
    },
  });
}

