import { NextRequest, NextResponse } from "next/server";
import { createRefineStream } from "@/lib/llm";
import { checkAuth } from "@/lib/auth";
import type { RefineRequest } from "@/lib/types";

export const runtime = "nodejs";
export const maxDuration = 240;

const MAX_INPUT_CHARS = 8000;

export async function POST(req: NextRequest) {
  const unauthorized = checkAuth(req);
  if (unauthorized) return unauthorized;

  let body: Partial<RefineRequest>;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "请求体不是合法 JSON" }, { status: 400 });
  }

  const text = (body.text ?? "").toString();
  const original = (body.original ?? "").toString();
  if (!text.trim()) {
    return NextResponse.json({ error: "缺少要精修的文案" }, { status: 400 });
  }
  if ([...text].length > MAX_INPUT_CHARS) {
    return NextResponse.json({ error: "文案过长,无法精修" }, { status: 413 });
  }

  const payload: RefineRequest = {
    text,
    original: original.trim() ? original : text,
    sourceLang: body.sourceLang || "auto",
    targetLang: body.targetLang || "same",
    channel: typeof body.channel === "string" ? body.channel : "",
    background: typeof body.background === "string" ? body.background : "",
    focus: typeof body.focus === "string" ? body.focus : "",
    // 精修默认走专家档(开思考)求质量;前端不传则用 pro
    mode: typeof body.mode === "string" ? body.mode : "pro",
  };

  const encoder = new TextEncoder();
  const readable = new ReadableStream({
    async start(controller) {
      const send = (frame: { r: string } | { c: string } | { e: string }) =>
        controller.enqueue(encoder.encode(JSON.stringify(frame) + "\n"));
      try {
        const stream = await createRefineStream(payload);
        for await (const part of stream) {
          const delta = part.choices?.[0]?.delta as
            | { content?: string; reasoning_content?: string }
            | undefined;
          if (!delta) continue;
          if (delta.reasoning_content) send({ r: delta.reasoning_content });
          if (delta.content) send({ c: delta.content });
        }
      } catch (err) {
        const message = err instanceof Error ? err.message : "精修失败,请重试";
        send({ e: message });
      } finally {
        controller.close();
      }
    },
  });

  return new Response(readable, {
    headers: {
      "Content-Type": "application/x-ndjson; charset=utf-8",
      "Cache-Control": "no-cache, no-transform",
    },
  });
}

