// 解析「单个版本对象」的流式缓冲(并发槽位 / 精修都用单对象格式)。
// 优先整体 JSON.parse;失败则退化为逐字段提取,text 未闭合也先返回已写出的部分。
export function extractSingleVariant(buf: string): PolishVariant | null {
  const trimmed = buf.trim();
  if (trimmed) {
    try {
      const v = coerceVariant(JSON.parse(trimmed));
      if (v) return v;
    } catch {
      // 还没闭合,走下面的流式提取
    }
  }

  const t = extractStringField(buf, "text");
  if (!t || !t.value.trim()) return null;

  const f = extractStringField(buf, "focus");
  const intent = extractStringField(buf, "intent");
  const reason = extractStringField(buf, "reason");
  return {
    focus: f && f.value.trim() ? f.value : "版本",
    text: t.value,
    intent: intent?.closed ? intent.value : "",
    reason: reason?.closed ? reason.value : "",
    charCount: [...t.value].length,
  };
}

