"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import LanguageSelector from "@/components/LanguageSelector";
import StylePalette from "@/components/StylePalette";
import TerminologyManager from "@/components/admin/TerminologyManager";
import FileDropzone from "@/components/FileDropzone";
import ResultCard from "@/components/ResultCard";
import ThinkingIndicator from "@/components/ThinkingIndicator";
import { MODES } from "@/lib/models";
import { extractSingleVariant, extractDetectedLang } from "@/lib/parseStream";
import { applyGuards, buildSourceText, brandNumberSet } from "@/lib/guards";
import { authFetch } from "@/lib/clientAuth";
import type { PolishVariant } from "@/lib/types";

const CHANNELS = ["不限", "电商 listing", "社媒帖", "广告语", "邮件 EDM", "包装文案"];

// 并发槽位数(与后端 VARIANT_SLOTS 对应),仅用于加载时占位骨架数量
const EXPECTED_SLOTS = 3;

function canParseFull(buf: string): boolean {
  const t = buf.trim();
  if (!t) return false;
  try {
    JSON.parse(t);
    return true;
  } catch {
    return false;
  }
}

export default function Home() {
  const [input, setInput] = useState("");
  const [source, setSource] = useState("auto");
  const [target, setTarget] = useState("same");
  const [channel, setChannel] = useState("不限");
  const [mode, setMode] = useState("normal");
  const [styleIds, setStyleIds] = useState<string[]>([]);
  const [background, setBackground] = useState("");
  const [bgName, setBgName] = useState("");
  const [termOpen, setTermOpen] = useState(false);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [slotVariants, setSlotVariants] = useState<(PolishVariant | null)[]>([]);
  const [slotErrors, setSlotErrors] = useState<string[]>([]);
  const [slotDone, setSlotDone] = useState<boolean[]>([]);
  const [detectedLang, setDetectedLang] = useState<string | undefined>();
  const [reasoning, setReasoning] = useState("");
  const [refiningIdx, setRefiningIdx] = useState<number | null>(null);

  // 护栏所需的(运行时可编辑的)品牌事实派生数据
  const [bannedPhrases, setBannedPhrases] = useState<string[]>([]);
  const [brandNumbers, setBrandNumbers] = useState<Set<string>>(new Set());

  // 页面加载即后台预热,消除首次请求的冷启动延迟(连接 + 前缀缓存)
  useEffect(() => {
    if (sessionStorage.getItem("warmed")) return;
    sessionStorage.setItem("warmed", "1");
    fetch("/api/warmup").catch(() => {});
  }, []);

  // 取品牌事实,供前端护栏(违禁词 + 数字白名单)使用
  useEffect(() => {
    fetch("/api/brand-facts")
      .then((r) => (r.ok ? r.json() : null))
      .then((facts) => {
        if (!facts) return;
        setBannedPhrases(facts?.compliance?.bannedPhrases ?? []);
        setBrandNumbers(brandNumberSet(JSON.stringify(facts)));
      })
      .catch(() => {});
  }, []);

  function toggleStyle(id: string) {
    setStyleIds((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]
    );
  }

  function swapLangs() {
    if (source === "auto" || target === "same") return;
    setSource(target);
    setTarget(source);
  }

  async function run() {
    if (!input.trim()) {
      setError("请先输入要润色的文案");
      return;
    }
    setLoading(true);
    setError("");
    setSlotVariants([]);
    setSlotErrors([]);
    setSlotDone([]);
    setDetectedLang(undefined);
    setReasoning("");
    const sourceText = buildSourceText(input, background);

    try {
      const res = await authFetch("/api/polish", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          input,
          sourceLang: source,
          targetLang: target,
          styleIds,
          background,
          channel: channel === "不限" ? "" : channel,
          mode,
        }),
      });

      if (!res.ok || !res.body) {
        const data = await res.json().catch(() => ({}));
        setError(data.error || "生成失败");
        return;
      }

      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let frameBuf = "";
      const contentBufs: string[] = [];
      const reasoningBufs: string[] = [];
      const errs: string[] = [];

      const ensure = (i: number) => {
        while (contentBufs.length <= i) {
          contentBufs.push("");
          reasoningBufs.push("");
          errs.push("");
        }
      };

      const pushFrame = (line: string) => {
        if (!line) return;
        try {
          const obj = JSON.parse(line) as {
            i?: number;
            c?: string;
            r?: string;
            e?: string;
          };
          if (typeof obj.i !== "number") return;
          ensure(obj.i);
          if (typeof obj.c === "string") contentBufs[obj.i] += obj.c;
          if (typeof obj.r === "string") reasoningBufs[obj.i] += obj.r;
          if (typeof obj.e === "string") errs[obj.i] = obj.e;
        } catch {
          // 非法帧:忽略
        }
      };

      const render = () => {
        const variants = contentBufs.map((b) => {
          const v = extractSingleVariant(b);
          return v ? applyGuards(v, sourceText, bannedPhrases, brandNumbers) : null;
        });
        setSlotVariants(variants);
        setSlotErrors([...errs]);
        setSlotDone(contentBufs.map(canParseFull));
        const detected = contentBufs.map(extractDetectedLang).find(Boolean);
        if (detected) setDetectedLang(detected);
        const r = reasoningBufs.filter(Boolean).join("\n\n");
        if (r) setReasoning(r);
      };

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        frameBuf += decoder.decode(value, { stream: true });
        let nl: number;
        while ((nl = frameBuf.indexOf("\n")) >= 0) {
          pushFrame(frameBuf.slice(0, nl));
          frameBuf = frameBuf.slice(nl + 1);
        }
        render();
      }
      if (frameBuf) pushFrame(frameBuf);
      render();

      const anyVariant = contentBufs.some((b) => extractSingleVariant(b));
      if (!anyVariant) {
        const firstErr = errs.find(Boolean);
        setError(firstErr || "模型未返回有效的文案版本,请重试");
      }
    } catch {
      setError("请求失败,请检查网络或稍后重试");
    } finally {
      setLoading(false);
    }
  }

  // 精修:对某一版做第二轮润色,流式替换该卡内容
  async function refine(index: number) {
    const current = slotVariants[index];
    if (!current || refiningIdx !== null) return;
    setRefiningIdx(index);
    const sourceText = buildSourceText(input, background);
    try {
      const res = await authFetch("/api/refine", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          text: current.text,
          original: input,
          sourceLang: source,
          targetLang: target,
          channel: channel === "不限" ? "" : channel,
          background,
          focus: current.focus,
        }),
      });
      if (!res.ok || !res.body) return;

      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let frameBuf = "";
      let contentBuf = "";

      const pushFrame = (line: string) => {
        if (!line) return;
        try {
          const obj = JSON.parse(line) as { c?: string; r?: string; e?: string };
          if (typeof obj.c === "string") contentBuf += obj.c;
        } catch {
          // 忽略
        }
      };

      const apply = () => {
        const v = extractSingleVariant(contentBuf);
        if (!v) return;
        const guarded = applyGuards(v, sourceText, bannedPhrases, brandNumbers);
        setSlotVariants((prev) =>
          prev.map((x, i) => (i === index ? guarded : x))
        );
      };

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        frameBuf += decoder.decode(value, { stream: true });
        let nl: number;
        while ((nl = frameBuf.indexOf("\n")) >= 0) {
          pushFrame(frameBuf.slice(0, nl));
          frameBuf = frameBuf.slice(nl + 1);
        }
        apply();
      }
      if (frameBuf) pushFrame(frameBuf);
      apply();
    } catch {
      // 精修失败:保留原版,不打断用户
    } finally {
      setRefiningIdx(null);
    }
  }

  const hasAnyVariant = slotVariants.some(Boolean);
  const slotCount = loading
    ? Math.max(EXPECTED_SLOTS, slotVariants.length)
    : slotVariants.length;

  return (
    <main className="mx-auto max-w-5xl px-4 py-8">
      <header className="mb-6 flex items-end justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-ink">文案副驾</h1>
          <p className="mt-0.5 text-sm text-ink-faint">品牌文案润色与跨语言美化 · 韶音</p>
        </div>
        <Link href="/admin" className="text-sm text-brand-dark hover:underline">
          运营编辑台
        </Link>
      </header>

      {/* 主面板:单一容器,左右分隔 */}
      <div className="overflow-hidden rounded-2xl border border-gray-200 bg-white shadow-sm">
        <LanguageSelector
          source={source}
          target={target}
          onSourceChange={setSource}
          onTargetChange={setTarget}
          onSwap={swapLangs}
        />

        <div className="grid grid-cols-1 divide-y divide-gray-200 md:grid-cols-2 md:divide-x md:divide-y-0">
          {/* 左:输入 */}
          <div className="flex min-h-[440px] flex-col">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="键入要润色或翻译的文案…"
              className="flex-1 resize-none border-0 bg-transparent p-5 text-[17px] leading-relaxed text-ink placeholder:text-ink-faint focus:outline-none focus:ring-0"
            />
            <div className="flex items-center gap-3 border-t border-gray-100 px-4 py-2.5">
              <FileDropzone
                variant="inline"
                label="上传文档"
                onParsed={(text) => setInput(text)}
              />
              <span className="text-xs text-ink-faint">{[...input].length} 字</span>
              <button
                type="button"
                onClick={run}
                disabled={loading}
                className="ml-auto rounded-lg bg-brand px-5 py-2 text-sm font-semibold text-white transition hover:bg-brand-dark disabled:opacity-60"
              >
                {loading ? "生成中…" : "美化文案"}
              </button>
            </div>
          </div>

          {/* 右:结果(多版本并发,逐卡显示) */}
          <div className="min-h-[440px] bg-gray-50/40 p-5">
            {error && !loading && (
              <div className="flex h-full min-h-[380px] items-center justify-center text-sm text-red-600">
                {error}
              </div>
            )}

            {!error && (hasAnyVariant || loading) && (
              <div className="space-y-3">
                {detectedLang && (
                  <p className="text-xs text-ink-faint">
                    识别原文语言:{detectedLang}
                  </p>
                )}
                {Array.from({ length: slotCount }, (_, i) => {
                  const v = slotVariants[i];
                  const err = slotErrors[i];
                  if (v) {
                    return (
                      <ResultCard
                        key={i}
                        variant={v}
                        index={i}
                        streaming={loading && !slotDone[i]}
                        original={input}
                        sameLanguage={target === "same" || target === source}
                        onRefine={() => refine(i)}
                        refining={refiningIdx === i}
                      />
                    );
                  }
                  if (err && !loading) {
                    return (
                      <div
                        key={i}
                        className="rounded-xl border border-red-100 bg-red-50 px-4 py-3 text-xs text-red-600"
                      >
                        第 {i + 1} 版生成失败:{err}
                      </div>
                    );
                  }
                  if (loading) {
                    return (
                      <div
                        key={i}
                        className="h-24 animate-pulse rounded-xl border border-gray-100 bg-white/70"
                      />
                    );
                  }
                  return null;
                })}
                {loading && reasoning && (
                  <div className="pt-1">
                    <ThinkingIndicator thinking={reasoning} />
                  </div>
                )}
              </div>
            )}

            {!error && !loading && !hasAnyVariant && (
              <div className="flex h-full min-h-[380px] items-center justify-center text-center text-sm text-ink-faint">
                美化结果会显示在这里
                <br />
                同时并发出多个版本
              </div>
            )}
          </div>
        </div>
      </div>

      {/* 选项区:模式 / 渠道 / 风格 / 背景 */}
      <div className="mt-4 space-y-3">
        <div className="flex flex-wrap items-center gap-3">
          <label className="text-sm text-ink-soft">模式</label>
          <div className="inline-flex rounded-lg border border-gray-200 bg-white p-0.5">
            {MODES.map((m) => (
              <button
                key={m.id}
                type="button"
                title={m.hint}
                onClick={() => setMode(m.id)}
                className={
                  "rounded-md px-3 py-1.5 text-sm transition " +
                  (mode === m.id
                    ? "bg-brand text-white"
                    : "text-ink-soft hover:text-brand")
                }
              >
                {m.label}
              </button>
            ))}
          </div>

          <label className="ml-2 text-sm text-ink-soft">渠道</label>
          <select
            value={channel}
            onChange={(e) => setChannel(e.target.value)}
            className="rounded-lg border border-gray-200 bg-white px-3 py-2 text-sm focus:border-brand focus:outline-none focus:ring-1 focus:ring-brand"
          >
            {CHANNELS.map((c) => (
              <option key={c} value={c}>
                {c}
              </option>
            ))}
          </select>

          <div className="ml-auto flex items-center gap-2">
            <FileDropzone
              variant="inline"
              label="上传背景资料"
              onParsed={(text, name) => {
                setBackground(text);
                setBgName(name);
              }}
            />
            {bgName && (
              <span className="text-xs text-ink-faint">
                {bgName}
                <button
                  type="button"
                  className="ml-1 text-brand-dark"
                  onClick={() => {
                    setBackground("");
                    setBgName("");
                  }}
                >
                  移除
                </button>
              </span>
            )}
          </div>
        </div>

        <StylePalette selected={styleIds} onToggle={toggleStyle} />

        <div className="rounded-lg border border-gray-200 bg-white">
          <button
            type="button"
            onClick={() => setTermOpen((v) => !v)}
            className="flex w-full items-center justify-between px-4 py-3 text-left text-sm font-medium text-ink"
          >
            <span>
              专有术语库
              <span className="ml-2 font-normal text-ink-faint">
                翻译时统一术语拼写 · 可在此查询与编辑
              </span>
            </span>
            <span className="text-ink-faint">{termOpen ? "收起" : "展开"}</span>
          </button>
          {termOpen && (
            <div className="border-t border-gray-100 px-4 py-3">
              <TerminologyManager compact />
            </div>
          )}
        </div>
      </div>
    </main>
  );
}

