/** @type {import('next').NextConfig} */
const nextConfig = {
  // 打包桌面 App 用:产出自带最小 node 服务的 .next/standalone,Electron 直接拉起它
  output: "standalone",
  serverExternalPackages: ["pdf-parse", "mammoth"],
  devIndicators: false,
};

export default nextConfig;

// Electron 主进程:拉起内嵌的 Next standalone 服务,再用窗口加载它。
// 关键点:用 Electron 自带的 Node(process.execPath + ELECTRON_RUN_AS_NODE)跑 server.js,
// 因此终端用户无需安装 Node。API Key 留在主进程读取的 .env.local 里,不进前端 JS。
const { app, BrowserWindow, shell } = require("electron");
const { spawn } = require("node:child_process");
const http = require("node:http");
const path = require("node:path");
const fs = require("node:fs");

const HOST = "127.0.0.1";
let serverProcess = null;
let mainWindow = null;

function standaloneDir() {
  // 已打包:资源在 resources/standalone;开发:项目内 .next/standalone
  return app.isPackaged
    ? path.join(process.resourcesPath, "standalone")
    : path.join(__dirname, "..", ".next", "standalone");
}

// 读取 standalone 目录下的 .env.local(简单 KEY=VALUE),注入子进程环境。
function loadEnv(dir) {
  const file = path.join(dir, ".env.local");
  const env = {};
  try {
    const raw = fs.readFileSync(file, "utf-8");
    for (const line of raw.split(/\r?\n/)) {
      const t = line.trim();
      if (!t || t.startsWith("#")) continue;
      const eq = t.indexOf("=");
      if (eq < 0) continue;
      env[t.slice(0, eq).trim()] = t.slice(eq + 1).trim();
    }
  } catch {
    // 没有 .env.local 就算了,交给系统环境变量
  }
  return env;
}

async function findFreePort() {
  return new Promise((resolve, reject) => {
    const srv = http.createServer();
    srv.listen(0, HOST, () => {
      const port = srv.address().port;
      srv.close(() => resolve(port));
    });
    srv.on("error", reject);
  });
}

function waitForServer(port, timeoutMs = 30000) {
  const deadline = Date.now() + timeoutMs;
  return new Promise((resolve, reject) => {
    const tryOnce = () => {
      const req = http.get(
        { host: HOST, port, path: "/", timeout: 2000 },
        (res) => {
          res.destroy();
          resolve();
        }
      );
      req.on("error", () => {
        if (Date.now() > deadline) reject(new Error("server start timeout"));
        else setTimeout(tryOnce, 300);
      });
      req.on("timeout", () => {
        req.destroy();
        if (Date.now() > deadline) reject(new Error("server start timeout"));
        else setTimeout(tryOnce, 300);
      });
    };
    tryOnce();
  });
}

async function startServer() {
  const dir = standaloneDir();
  const serverJs = path.join(dir, "server.js");
  if (!fs.existsSync(serverJs)) {
    throw new Error(
      "找不到 standalone/server.js,请先运行 npm run build:standalone"
    );
  }
  const port = await findFreePort();
  serverProcess = spawn(process.execPath, [serverJs], {
    cwd: dir,
    env: {
      ...process.env,
      ...loadEnv(dir),
      ELECTRON_RUN_AS_NODE: "1",
      PORT: String(port),
      HOSTNAME: HOST,
    },
    stdio: "inherit",
  });
  serverProcess.on("exit", (code) => {
    if (code && code !== 0 && !app.isQuitting) {
      console.error("Next 服务退出,code=", code);
    }
  });
  await waitForServer(port);
  return port;
}

async function createWindow() {
  mainWindow = new BrowserWindow({
    width: 1200,
    height: 860,
    backgroundColor: "#ffffff",
    title: "文案副驾",
    webPreferences: { contextIsolation: true },
  });
  // 外链在系统浏览器打开,不在应用窗口里跳走
  mainWindow.webContents.setWindowOpenHandler(({ url }) => {
    shell.openExternal(url);
    return { action: "deny" };
  });
  try {
    const port = await startServer();
    await mainWindow.loadURL(`http://${HOST}:${port}`);
  } catch (err) {
    await mainWindow.loadURL(
      "data:text/html;charset=utf-8," +
        encodeURIComponent(
          `<h2 style="font-family:sans-serif">启动失败</h2><pre>${String(
            err
          )}</pre>`
        )
    );
  }
}

app.whenReady().then(createWindow);

app.on("activate", () => {
  if (BrowserWindow.getAllWindows().length === 0) createWindow();
});

app.on("window-all-closed", () => {
  if (process.platform !== "darwin") app.quit();
});

app.on("before-quit", () => {
  app.isQuitting = true;
  if (serverProcess && !serverProcess.killed) serverProcess.kill();
});

// next build(output: standalone)产出的 .next/standalone 不含静态资源与运行时数据,
// 这里把它们补齐,使 server.js 能独立运行,供 Electron 拉起。
import { existsSync, cpSync } from "node:fs";
import { join } from "node:path";

const root = process.cwd();
const standalone = join(root, ".next", "standalone");

if (!existsSync(standalone)) {
  console.error("缺少 .next/standalone,请先运行 next build(已开启 output:standalone)");
  process.exit(1);
}

function copy(from, to, label) {
  if (!existsSync(from)) {
    console.log(`跳过 ${label}(不存在:${from})`);
    return;
  }
  cpSync(from, to, { recursive: true });
  console.log(`已复制 ${label}`);
}

// 前端静态资源(JS/CSS/字体等)
copy(
  join(root, ".next", "static"),
  join(standalone, ".next", "static"),
  ".next/static"
);
// public(若有)
copy(join(root, "public"), join(standalone, "public"), "public");
// 运行时数据:品牌事实 / 术语 / 风格 / few-shot,server.js 以 cwd 读取
copy(join(root, "data"), join(standalone, "data"), "data");
// 密钥与模型配置:随包内置(内部自用;注意安装包内可被提取)
copy(
  join(root, ".env.local"),
  join(standalone, ".env.local"),
  ".env.local"
);

console.log("standalone 准备完成,可运行 npm run electron:dev 或 npm run app:build");

