// next build(output: standalone)产出的 .next/standalone 不含静态资源与运行时数据,
// 这里把它们补齐,使 server.js 能独立运行,供 Electron 拉起。
//
// 注意:不用 fs.cpSync({recursive}) —— 它在部分 Windows/Node 组合下会硬崩溃(0xC0000409),
// 改为手写递归 + copyFileSync,稳。
import {
  existsSync,
  mkdirSync,
  readdirSync,
  copyFileSync,
} from "node:fs";
import { join, dirname } from "node:path";

const root = process.cwd();
const standalone = join(root, ".next", "standalone");

if (!existsSync(standalone)) {
  console.error("缺少 .next/standalone,请先运行 next build(已开启 output:standalone)");
  process.exit(1);
}

function copyDir(from, to) {
  mkdirSync(to, { recursive: true });
  for (const entry of readdirSync(from, { withFileTypes: true })) {
    const s = join(from, entry.name);
    const d = join(to, entry.name);
    if (entry.isDirectory()) copyDir(s, d);
    else if (entry.isFile()) copyFileSync(s, d);
  }
}

function copyFile(from, to) {
  mkdirSync(dirname(to), { recursive: true });
  copyFileSync(from, to);
}

function copy(from, to, label, isFile = false) {
  if (!existsSync(from)) {
    console.log(`跳过 ${label}(不存在:${from})`);
    return;
  }
  if (isFile) copyFile(from, to);
  else copyDir(from, to);
  console.log(`已复制 ${label}`);
}

// 前端静态资源(JS/CSS/字体等)
copy(
  join(root, ".next", "static"),
  join(standalone, ".next", "static"),
  ".next/static"
);
// public(若有)
copy(join(root, "public"), join(standalone, "public"), "public");
// 运行时数据:品牌事实 / 术语 / 风格 / few-shot,server.js 以 cwd 读取
copy(join(root, "data"), join(standalone, "data"), "data");
// 密钥与模型配置:随包内置(内部自用;注意安装包内可被提取)
copy(
  join(root, ".env.local"),
  join(standalone, ".env.local"),
  ".env.local",
  true
);

console.log("standalone 准备完成,可运行 npm run electron:dev 或 npm run app:build");

// 一键产出可被 Electron 拉起的 standalone 包。
//
// 为什么不用 "next build && node prepare":
// Next 16 + Turbopack 在 Windows 上常于「构建完成、进程退出」时崩溃(0xC0000409),
// 返回非零退出码,导致 && 后面的步骤不执行——但此时产物其实已经生成。
// 这里改为:跑完 next build 后以「产物是否存在」判定成功,绕开这个伪失败。
import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import { join } from "node:path";

const root = process.cwd();
const isWin = process.platform === "win32";

spawnSync(isWin ? "npx.cmd" : "npx", ["next", "build"], { stdio: "inherit" });

if (!existsSync(join(root, ".next", "standalone", "server.js"))) {
  console.error("✗ next build 未产出 .next/standalone/server.js,构建失败");
  process.exit(1);
}

const prep = spawnSync(process.execPath, ["scripts/prepare-standalone.mjs"], {
  stdio: "inherit",
});
process.exit(prep.status ?? 0);

// 评测工具:对固定测试集跑 /api/polish,测「首卡耗时」「总耗时」「版本数」。
// 用途:
//   1) 模型横评:改 .env.local 的 OPENAI_MODEL → 重启服务 → 重跑,比不同模型的质量/延迟/成本。
//   2) 改造前后对比:在旧代码上跑一次存基线,新代码再跑,比首卡/总耗时。
//
// 前置:先启动服务(npm run dev 或 npm start),默认 http://127.0.0.1:3000。
// 用法:
//   node scripts/eval.mjs                      # 标准档
//   $env:MODE="pro"; node scripts/eval.mjs     # 专家档(开思考)
//   $env:BASE_URL="http://127.0.0.1:3939"; node scripts/eval.mjs
//   $env:APP_PASSWORD="xxx"; node scripts/eval.mjs   # 若服务端开了门禁
//
// 质量分需人工填:结果 JSON 里每条留了 "humanScore": null,跑完后人工 1-5 打分。
import { readFileSync, mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const BASE_URL = process.env.BASE_URL || "http://127.0.0.1:3000";
const MODE = process.env.MODE || "normal";
const PASSWORD = process.env.APP_PASSWORD || "";
const root = process.cwd();

const testset = JSON.parse(
  readFileSync(join(root, "eval", "testset.json"), "utf-8")
);

function canParse(s) {
  const t = s.trim();
  if (!t) return false;
  try {
    JSON.parse(t);
    return true;
  } catch {
    return false;
  }
}

async function runCase(tc) {
  const body = {
    input: tc.input,
    sourceLang: tc.sourceLang || "auto",
    targetLang: tc.targetLang || "same",
    channel: tc.channel === "不限" ? "" : tc.channel || "",
    styleIds: [],
    background: "",
    mode: MODE,
  };

  const headers = { "Content-Type": "application/json" };
  if (PASSWORD) headers["x-app-password"] = PASSWORD;

  const t0 = Date.now();
  const res = await fetch(`${BASE_URL}/api/polish`, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
  });
  if (!res.ok || !res.body) {
    return { id: tc.id, ok: false, error: `HTTP ${res.status}` };
  }

  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  const contentBufs = [];
  let frameBuf = "";
  let firstCardMs = null;
  const ensure = (i) => {
    while (contentBufs.length <= i) contentBufs.push("");
  };

  const checkFirstCard = () => {
    if (firstCardMs !== null) return;
    if (contentBufs.some(canParse)) firstCardMs = Date.now() - t0;
  };

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    frameBuf += decoder.decode(value, { stream: true });
    let nl;
    while ((nl = frameBuf.indexOf("\n")) >= 0) {
      const line = frameBuf.slice(0, nl);
      frameBuf = frameBuf.slice(nl + 1);
      if (!line) continue;
      try {
        const obj = JSON.parse(line);
        if (typeof obj.i === "number" && typeof obj.c === "string") {
          ensure(obj.i);
          contentBufs[obj.i] += obj.c;
        }
      } catch {
        // 忽略非法帧
      }
    }
    checkFirstCard();
  }
  const totalMs = Date.now() - t0;

  const variants = contentBufs.filter(canParse).length;
  return {
    id: tc.id,
    ok: variants > 0,
    firstCardMs,
    totalMs,
    variants,
    humanScore: null,
  };
}

async function main() {
  console.log(`评测中… BASE_URL=${BASE_URL} MODE=${MODE} 用例=${testset.length}`);
  const results = [];
  for (const tc of testset) {
    process.stdout.write(`- ${tc.id} … `);
    try {
      const r = await runCase(tc);
      results.push(r);
      console.log(
        r.ok
          ? `首卡 ${r.firstCardMs}ms / 总 ${r.totalMs}ms / ${r.variants} 版`
          : `失败:${r.error || "无有效版本"}`
      );
    } catch (e) {
      results.push({ id: tc.id, ok: false, error: String(e) });
      console.log(`异常:${e}`);
    }
  }

  const ok = results.filter((r) => r.ok);
  const avg = (xs) =>
    xs.length ? Math.round(xs.reduce((a, b) => a + b, 0) / xs.length) : null;
  const summary = {
    baseUrl: BASE_URL,
    mode: MODE,
    model: "见服务端 OPENAI_MODEL(脚本侧不可见)",
    when: new Date().toISOString(),
    cases: results.length,
    okCases: ok.length,
    avgFirstCardMs: avg(ok.map((r) => r.firstCardMs).filter((x) => x != null)),
    avgTotalMs: avg(ok.map((r) => r.totalMs)),
    results,
  };

  mkdirSync(join(root, "eval", "results"), { recursive: true });
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const out = join(root, "eval", "results", `${MODE}-${stamp}.json`);
  writeFileSync(out, JSON.stringify(summary, null, 2) + "\n", "utf-8");

  console.log("");
  console.log(`平均首卡 ${summary.avgFirstCardMs}ms / 平均总 ${summary.avgTotalMs}ms`);
  console.log(`结果已写入 ${out}`);
  console.log("下一步:人工给每条 results[].humanScore 打 1-5 分,再比模型/前后版本。");
}

main();

// 用 electron-builder 打 Windows 安装包。
//
// 为什么输出到 ~/copywrite-dist 而不是项目内 dist-electron:
// 本项目在 OneDrive 同步目录下,electron-builder 解压 electron 时会被 OneDrive 锁文件,
// 触发 EPERM: rename win-unpacked.tmp -> win-unpacked。输出到 OneDrive 外的目录可绕开。
import { spawnSync } from "node:child_process";
import { join } from "node:path";
import { homedir } from "node:os";

const out = join(homedir(), "copywrite-dist").replace(/\\/g, "/");
const isWin = process.platform === "win32";

const r = spawnSync(
  isWin ? "npx.cmd" : "npx",
  ["electron-builder", "--win", `--config.directories.output=${out}`],
  { stdio: "inherit" }
);

if ((r.status ?? 0) === 0) {
  console.log(`\n✓ 安装包已生成:${out}`);
  console.log("  · 文案副驾 Setup 0.1.0.exe(安装版)");
  console.log("  · 文案副驾 0.1.0.exe(免安装,双击即用)");
}
process.exit(r.status ?? 0);

