        }
      }
      if (firstCardMs === null && bufs.some(canParse)) firstCardMs = Date.now() - t0;
    }
    const totalMs = Date.now() - t0;

    const variants = bufs.filter(canParse).map((b) => JSON.parse(b));
    log(`- HTTP ${res.status} · 首卡 ${firstCardMs}ms · 总 ${totalMs}ms`);
    log(`- detectedSourceLang: ${variants.find((v) => v.detectedSourceLang)?.detectedSourceLang ?? "(无)"}`);
    log(`- 变体数: ${variants.length}`);
    variants.forEach((v, i) => {
      const risks = v.risks?.length ? ` ⚠[${v.risks.join("; ")}]` : "";
      log(`  ${i + 1}. (${v.focus}) ${v.text}${risks}`);
    });
    log("");
  } catch (e) {
    log(`### ${name}`);
    log(`- 请求异常: ${e.message}`);
    log("");
  }
}
